def refs():
    return [{**s, "subject": "science", "locator": "碳循環、光合作用、呼吸作用、分解、燃燒與生物／非生物間的碳交換", "observedPattern": "公開公立學校生物資料常用碳循環圖、作用配對和生物量變化判讀，要求區分元素循環與能量流動；本題只採能力方向與資料型態。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, answer, explanation, strategy, steps, difficulty):
    return {"id": f"question-science-content-bd-iv-2-{n}", "subject": "science", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": answer, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三筆公立學校公開生物科資料僅供碳循環、光合作用、呼吸作用、分解與燃燒的能力方向研究；本題未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與三筆公開公立學校生物科資料的能力方向獨立改寫；題幹、選項、答案、解析與五步解法均為原創，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-10", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
    make(1, "植物透過哪個作用把大氣中的二氧化碳固定進有機物，成為碳循環的一個入口？", {"A": "光合作用", "B": "蒸發", "C": "肌肉收縮", "D": "聲音傳播"}, "A", "植物進行光合作用時吸收二氧化碳並合成醣類，使碳進入生物體，選 A。", "先找大氣二氧化碳進入生物有機物的作用。", ["確認題目問的是碳進入生物體的路徑。", "植物吸收大氣中的二氧化碳。", "光合作用把碳納入醣類等有機物。", "蒸發和聲音不涉及碳固定。", "所以選 A。"], "easy"),
    make(2, "動物呼吸作用會使有機物中的碳以哪種形式回到大氣？", {"A": "二氧化碳", "B": "葉綠素", "C": "澱粉顆粒", "D": "氧氣分子中的碳"}, "A", "呼吸作用分解有機物並產生二氧化碳，二氧化碳可回到大氣成為碳循環的一部分，選 A。", "把反應物中的有機碳追蹤到呼吸產物。", ["有機物含有碳元素。", "呼吸作用分解有機物供能。", "碳可組成二氧化碳。", "二氧化碳經換氣回到環境。", "因此選 A。"], "easy"),
    make(3, "分解者在碳循環中的主要作用是？", {"A": "分解遺體與排遺，讓碳以二氧化碳或無機物形式回到環境", "B": "把所有碳永久鎖在自己的身體內", "C": "只負責吸收太陽光不分解物質", "D": "使碳元素消失而不再循環"}, "A", "細菌與真菌等分解者分解有機遺體和排遺，呼吸與分解作用可使碳回到環境，選 A。", "將生物遺體和排遺視為碳離開活生物後的轉移節點。", ["遺體和排遺仍含有有機碳。", "分解者利用其中物質與能量。", "分解與呼吸可釋放二氧化碳等物質。", "碳回到環境後仍可被植物利用。", "所以選 A。"], "medium"),
    make(4, "燃燒森林或化石燃料會影響碳循環，主要因為哪項？", {"A": "把儲存在有機物中的碳較快轉成二氧化碳進入大氣", "B": "讓大氣中的所有碳消失", "C": "把二氧化碳直接轉成葉綠素", "D": "使碳只停留在燃料中不移動"}, "A", "燃燒把燃料或生物質中的碳氧化成二氧化碳，使碳較快由儲存庫移入大氣，選 A。", "先辨認燃燒前的碳庫，再追蹤燃燒後的氣體產物。", ["燃料或木材含有有機碳。", "燃燒時碳與氧反應。", "常見產物包含二氧化碳。", "因此大氣碳量可能增加。", "所以選 A。"], "medium"),
    make(5, "下列哪項最能說明碳元素會在生物與非生物環境間循環？", {"A": "二氧化碳被植物吸收成醣類，醣類又可經呼吸回成二氧化碳", "B": "碳只存在於植物，動物不含碳", "C": "碳一旦進入生物體就永不離開", "D": "碳循環只發生在一個細胞內"}, "A", "此路徑同時包含大氣二氧化碳、植物有機物和呼吸產生的二氧化碳，展示生物與非生物間的碳交換，選 A。", "找至少一個非生物碳庫和一個生物碳庫，再連接轉移作用。", ["大氣二氧化碳屬非生物環境中的碳。", "植物把它合成有機物。", "動物可攝食植物取得碳。", "呼吸與分解又把碳送回環境。", "所以選 A。"], "easy"),
    make(6, "若一大片森林被砍除並焚燒，短期內大氣二氧化碳最可能如何變化？", {"A": "可能增加，因燃燒釋放碳且植物固定二氧化碳的量下降", "B": "必定降到零", "C": "一定完全不變", "D": "只會變成氧氣而沒有二氧化碳"}, "A", "砍除降低植物固定二氧化碳的能力，焚燒又將生物質碳快速轉成二氧化碳，短期可能增加，選 A。", "同時看固定端減弱和釋放端增加兩條碳循環路徑。", ["森林植物原本可吸收二氧化碳。", "砍除使固定量減少。", "焚燒把木材有機碳轉成二氧化碳。", "兩個方向都可能使大氣二氧化碳上升。", "所以選 A。"], "medium"),
    make(7, "關於碳循環與能量流動，下列何者正確？", {"A": "碳元素可在環境與生物間循環，但能量經傳遞後部分以熱散失", "B": "碳元素和能量都會完全無損循環", "C": "能量會被分解者轉成新的太陽光", "D": "碳循環只在動物之間發生"}, "A", "元素可在不同碳庫間循環；能量則由太陽進入並在代謝與傳遞中逐步散失，不能混為一談，選 A。", "先分開畫物質箭頭與能量箭頭，再判斷是否循環及是否散失。", ["碳可經光合作用、攝食、呼吸與分解轉移。", "能量在生態系中沿營養階層傳遞。", "代謝會把部分能量轉成熱。", "因此物質循環不等於能量循環。", "所以選 A。"], "hard"),
    make(8, "海洋吸收大氣二氧化碳後，碳可能進入海洋生物或溶解碳庫。這說明碳循環具有哪種特性？", {"A": "碳可在大氣、水域與生物等不同碳庫間交換", "B": "碳只能在陸地植物間交換", "C": "海洋中的碳與生物完全無關", "D": "二氧化碳進入海洋後永遠不會再移動"}, "A", "海洋是重要碳庫，二氧化碳可溶解、被生物利用或再釋放，顯示不同環境碳庫間存在交換，選 A。", "把題目中的水域視為另一個碳庫，再找進出它的途徑。", ["大氣二氧化碳可溶入海水。", "溶解碳可能被海洋生物利用。", "呼吸、分解與物理交換又能改變其位置。", "所以碳可在多種碳庫間交換。", "因此選 A。"], "medium"),
    make(9, "若植物光合作用固定的二氧化碳量等於呼吸與分解釋放量，該區域大氣二氧化碳的淨變化較接近？", {"A": "在其他條件不變下，淨變化接近零", "B": "必定快速增加", "C": "必定快速減少", "D": "會變成氧氣而不再含碳"}, "A", "固定量和釋放量相等時，兩方向的碳通量互相抵消，淨變化接近零；實際仍需考慮其他輸入輸出，選 A。", "比較總流入和總流出，而不是只看單一作用。", ["列出固定二氧化碳的通量。", "列出呼吸與分解釋放的通量。", "兩者相等時相減後的淨值接近零。", "需注意燃燒、海氣交換等其他通量。", "所以在題目條件下選 A。"], "hard"),
    make(10, "某碳循環圖把『呼吸作用』箭頭畫成由大氣二氧化碳指向植物。最可能的修正是？", {"A": "把該箭頭改為植物有機物指向二氧化碳；大氣二氧化碳進入植物是光合作用", "B": "保留原箭頭，因為呼吸作用吸收二氧化碳", "C": "把箭頭改成植物指向氧氣但不含碳", "D": "刪除所有植物與大氣的連線"}, "A", "植物吸收大氣二氧化碳是光合作用；呼吸作用分解有機物並釋放二氧化碳，因此應改為 A 所述方向，選 A。", "看到圖中作用名稱時，先用反應物與產物檢查箭頭方向。", ["光合作用吸收二氧化碳合成有機物。", "呼吸作用分解有機物並產生二氧化碳。", "因此兩作用的碳箭頭方向相反。", "圖中標示呼吸作用卻畫成吸收二氧化碳需修正。", "所以選 A。"], "easy"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    old = {o["id"]: o["text"] for o in q["options"]}
    old["A"], old[target] = old[target], old["A"]
    q["options"] = [{"id": k, "text": old[k]} for k in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["answer"]["explanation"] = q["answer"]["explanation"].replace("選 A", f"選 {target}")
    q["solutionStrategy"] = q["solutionStrategy"].replace("選 A", f"選 {target}")
    q["solutionSteps"] = [s.replace("選 A", f"選 {target}").replace("所以選 A", f"所以選 {target}") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
